function activeNotebook() { return notebooks[currentNotebook]; }
function persistNotebooks() { try { localStorage.setItem(notebookStorage, JSON.stringify(notebooks)); } catch {} scheduleCloudSave(); }
function saveCurrent() { const page=activeNotebook().pages[currentPage]; page.content = $('#paperContent').innerHTML; page.stickers = $$('.placed-sticker').map(el => ({emoji:el.textContent,x:el.style.left,y:el.style.top}));if($('#drawingCanvas')?.width)page.drawing=$('#drawingCanvas').toDataURL('image/png'); persistNotebooks(); }
function renderNotebooks() { $('#notebookList').innerHTML = notebooks.map((n,i)=>`<div class="notebook-list-item"><button class="notebook-select ${i===currentNotebook?'active':''}" data-notebook="${i}"><span class="notebook-dot ${n.cover} ${n.cover}-cover" aria-hidden="true"></span><span class="notebook-name">${escapeHtml(n.title)}</span></button><button class="rename-notebook" data-rename-notebook="${i}" aria-label="Renomear ${escapeHtml(n.title)}" title="Renomear caderno">✎</button><button class="delete-notebook" data-delete-notebook="${i}" aria-label="Excluir ${escapeHtml(n.title)}" title="Excluir caderno" ${notebooks.length===1?'disabled':''}>🗑</button></div>`).join(''); $$('.notebook-select').forEach(b=>b.onclick=()=>loadNotebook(+b.dataset.notebook));$$('.rename-notebook').forEach(button=>button.onclick=()=>{const index=+button.dataset.renameNotebook,currentTitle=notebooks[index].title,newTitle=prompt('Qual será o novo nome do caderno?',currentTitle);if(!newTitle?.trim())return;notebooks[index].title=newTitle.trim();persistNotebooks();renderNotebooks();});$$('.delete-notebook').forEach(button=>button.onclick=()=>deleteNotebook(+button.dataset.deleteNotebook)); }
function deleteNotebook(index){if(notebooks.length===1)return;const notebook=notebooks[index];if(!confirm(`Excluir o caderno “${notebook.title}” e todas as suas folhas?`))return;saveCurrent();notebooks.splice(index,1);if(index<currentNotebook)currentNotebook--;else if(currentNotebook>=notebooks.length)currentNotebook=notebooks.length-1;persistNotebooks();loadNotebook(currentNotebook,false);}
function renderPages() { const pages=activeNotebook().pages;$('#pageList').innerHTML=pages.map((p,i)=>`<div class="page-list-item"><button class="page-select ${i===currentPage?'active':''}" data-page="${i}">▤ ${escapeHtml(p.title)}</button><button class="delete-page" data-delete-page="${i}" aria-label="Excluir ${escapeHtml(p.title)}" title="Excluir página" ${pages.length===1?'disabled':''}>✕</button></div>`).join('');$$('[data-page]').forEach(button=>button.onclick=()=>loadPage(+button.dataset.page));$$('[data-delete-page]').forEach(button=>button.onclick=()=>deletePage(+button.dataset.deletePage)); }
function deletePage(index){const pages=activeNotebook().pages;if(pages.length===1)return;const page=pages[index];if(!confirm(`Excluir ${page.title}?`))return;saveCurrent();pages.splice(index,1);pages.forEach((item,i)=>item.title=`Página ${i+1}`);if(index<currentPage)currentPage--;else if(currentPage>=pages.length)currentPage=pages.length-1;persistNotebooks();loadPage(currentPage,false);}
function loadPage(i, save=true) { if(save) saveCurrent(); currentPage=i; const p=activeNotebook().pages[i]; $('#paperContent').innerHTML=p.content; $('#stickerLayer').innerHTML=''; p.stickers.forEach(s=>placeSticker(s.emoji,s.x,s.y)); renderPages();requestAnimationFrame(()=>loadPageDrawing(p.drawing)); }
function loadNotebook(i, save=true) { if(save)saveCurrent(); currentNotebook=i; currentPage=0; const n=activeNotebook(); paperType=n.paperType; $('#notebook').className='notebook '+n.cover+'-cover'; $('#paper').className='paper '+paperType+'-paper'; $$('.cover-choice').forEach(b=>b.classList.toggle('selected',b.dataset.cover===n.cover)); $$('.paper-option').forEach(b=>b.classList.toggle('selected',b.dataset.paper===paperType)); renderNotebooks(); loadPage(0,false); }
let printNotebookIndex = 0, printPageIndex = 0;
function updatePrintPreview() { const notebook=notebooks[printNotebookIndex], page=notebook.pages[printPageIndex]; const paper=$('#printPaper'); paper.className='paper '+notebook.paperType+'-paper'; paper.innerHTML=`<div class="paper-content">${page.content}</div><div class="sticker-layer">${page.stickers.map(s=>`<span class="placed-sticker" style="left:${s.x};top:${s.y}">${s.emoji}</span>`).join('')}</div>`; }
function renderPrintOptions() { const notebookSelect=$('#printNotebookSelect'), pageSelect=$('#printPageSelect'); if (!notebookSelect || !pageSelect) return; if(printNotebookIndex>=notebooks.length) printNotebookIndex=0; notebookSelect.innerHTML=notebooks.map((n,i)=>`<option value="${i}">${n.title}</option>`).join(''); notebookSelect.value=printNotebookIndex; const notebook=notebooks[printNotebookIndex]; if(printPageIndex>=notebook.pages.length) printPageIndex=0; pageSelect.innerHTML=notebook.pages.map((p,i)=>`<option value="${i}">${p.title}</option>`).join(''); pageSelect.value=printPageIndex; updatePrintPreview(); }
function placeSticker(emoji, x='42%', y='42%') { const el=document.createElement('span'); el.className='placed-sticker'; el.textContent=emoji; el.style.left=x; el.style.top=y; el.setAttribute('aria-label','Adesivo '+emoji); enableDrag(el); $('#stickerLayer').append(el); }
function enableDrag(el) { let sx,sy,ox,oy; el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);sx=e.clientX;sy=e.clientY;ox=el.offsetLeft;oy=el.offsetTop;el.style.cursor='grabbing';}); el.addEventListener('pointermove',e=>{if(!el.hasPointerCapture(e.pointerId))return;const layer=$('#stickerLayer'), maxX=layer.clientWidth-el.offsetWidth, maxY=layer.clientHeight-el.offsetHeight;el.style.left=Math.max(0,Math.min(maxX,ox+e.clientX-sx))+'px';el.style.top=Math.max(0,Math.min(maxY,oy+e.clientY-sy))+'px';}); el.addEventListener('pointerup',e=>{el.releasePointerCapture(e.pointerId);el.style.cursor='grab';saveCurrent();}); el.addEventListener('dblclick',()=>{el.remove();saveCurrent();}); }

