$('#readPage').onclick=()=>{if(!('speechSynthesis'in window)){$('#speechStatus').textContent='A leitura em voz alta não está disponível neste navegador.';return;}window.speechSynthesis.cancel();const activePanel=$('.tab-panel.active'),text=activePanel?.innerText.replace(/\s+/g,' ').trim();if(!text){$('#speechStatus').textContent='Não há texto para ler nesta aba.';return;}pageSpeech=new SpeechSynthesisUtterance(text);pageSpeech.lang='pt-BR';pageSpeech.rate=.95;pageSpeech.onstart=()=>{$('#speechStatus').textContent='Leitura em voz alta iniciada.';$('#stopReading').disabled=false;};pageSpeech.onend=pageSpeech.onerror=()=>{$('#speechStatus').textContent='Leitura finalizada.';$('#stopReading').disabled=true;};window.speechSynthesis.speak(pageSpeech);};
