function setCloudStatus(message){const status=$('#sideLoginStatus');if(status)status.textContent=message;}
function scheduleCloudSave(){if(!cloudUser||!cloudReady)return;clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(saveNotebooksToCloud,900);}
async function saveNotebooksToCloud(){if(!cloudUser||!cloudReady)return;setCloudStatus('Salvando e sincronizando seus dados...');try{await cloudDb.collection('users').doc(cloudUser.uid).set({notebooks:JSON.parse(JSON.stringify(notebooks)),platformProgress:JSON.parse(JSON.stringify(platformProgress||{})),updatedAt:firebase.firestore.FieldValue.serverTimestamp(),updatedBy:cloudClientId},{merge:true});setCloudStatus('✓ Cadernos e progresso sincronizados em todos os aparelhos.');}catch(error){setCloudStatus(error?.code==='resource-exhausted'?'O caderno ficou grande demais para a nuvem. Apague desenhos muito pesados e tente novamente.':'Não foi possível salvar na nuvem agora. Suas alterações continuam salvas neste aparelho.');}}
function showCloudNotebooks(cloudNotebooks){if(!Array.isArray(cloudNotebooks)||!cloudNotebooks.length)return;notebooks=cloudNotebooks;currentNotebook=0;currentPage=0;const first=activeNotebook();paperType=first.paperType||'lined';$('#notebook').className='notebook '+first.cover+'-cover';$('#paper').className='paper '+paperType+'-paper';$$('.cover-choice').forEach(button=>button.classList.toggle('selected',button.dataset.cover===first.cover));$$('.paper-option').forEach(button=>button.classList.toggle('selected',button.dataset.paper===paperType));try{localStorage.setItem(notebookStorage,JSON.stringify(notebooks));}catch{}renderNotebooks();loadPage(0,false);}
function mergeNotebookCollections(remoteNotebooks,localNotebooks){const merged=[],seen=new Set();for(const source of [remoteNotebooks,localNotebooks])for(const original of source||[]){if(!original||!Array.isArray(original.pages))continue;const notebook=JSON.parse(JSON.stringify(original));if(!notebook.id)notebook.id=crypto.randomUUID();if(seen.has(notebook.id))continue;seen.add(notebook.id);merged.push(notebook);}return merged;}
async function startGoogleLogin(){saveCurrent();if(!cloudAuth){setCloudStatus('A conexão com a nuvem ainda está carregando. Tente novamente em alguns segundos.');return;}if(cloudUser){await cloudAuth.signOut();return;}setCloudStatus('Abrindo a página segura do Google...');const provider=new firebase.auth.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});try{await cloudAuth.signInWithPopup(provider);}catch(error){if(['auth/popup-blocked','auth/operation-not-supported-in-this-environment'].includes(error?.code)){setCloudStatus('Abrindo o Google em uma página segura...');try{await cloudAuth.signInWithRedirect(provider);return;}catch{}}setCloudStatus(error?.code==='auth/popup-closed-by-user'?'A janela do Google foi fechada antes de concluir a entrada.':'O Google não concluiu a entrada. Atualize a página e tente novamente.');}}
$('#sideGoogleLogin').onclick=startGoogleLogin;
if(window.firebase){firebase.initializeApp(firebaseConfig);cloudAuth=firebase.auth();cloudDb=firebase.firestore();cloudAuth.useDeviceLanguage();cloudAuth.getRedirectResult().catch(error=>setCloudStatus(error.code==='auth/unauthorized-domain'?'Este endereço ainda não foi autorizado para entrar com Google.':'O Google não concluiu a entrada. Toque no botão e tente novamente.'));cloudAuth.onAuthStateChanged(async user=>{if(cloudUnsubscribe){cloudUnsubscribe();cloudUnsubscribe=null;}cloudUser=user;cloudReady=false;if(!user){$('#sideGoogleLogin').innerHTML='<span aria-hidden="true">G</span> Continuar com Google';setCloudStatus('Entre com Google para salvar seus cadernos automaticamente na nuvem.');return;}$('#sideGoogleLogin').textContent='Sair da nuvem';setCloudStatus('Juntando os cadernos deste aparelho com os da nuvem...');const documentRef=cloudDb.collection('users').doc(user.uid);try{const snapshot=await documentRef.get(),remoteNotebooks=snapshot.exists?snapshot.data().notebooks:[];notebooks=mergeNotebookCollections(remoteNotebooks,notebooks);showCloudNotebooks(notebooks);cloudReady=true;await saveNotebooksToCloud();setCloudStatus(`✓ ${notebooks.length} caderno(s) sincronizado(s) em todos os aparelhos.`);cloudUnsubscribe=documentRef.onSnapshot(remote=>{const data=remote.data();if(!remote.exists||remote.metadata.hasPendingWrites||data?.updatedBy===cloudClientId||!Array.isArray(data?.notebooks))return;const combined=mergeNotebookCollections(data.notebooks,notebooks),received=combined.length>notebooks.length;showCloudNotebooks(combined);if(received){setCloudStatus('✓ Novos cadernos recebidos de outro aparelho.');scheduleCloudSave();}else setCloudStatus('✓ Alterações recebidas de outro aparelho.');},()=>setCloudStatus('A sincronização em tempo real foi interrompida. Verifique sua internet.'));}catch{cloudReady=true;setCloudStatus('Conta conectada, mas a nuvem ainda não respondeu. Tente novamente em instantes.');}});}
else setCloudStatus('Não foi possível carregar a conexão com a nuvem. Verifique sua internet.');
