function sizeDrawingCanvas(){const paper=$('#paper');if(paper.clientWidth<10||paper.clientHeight<10)return;const width=Math.round(paper.clientWidth),height=Math.round(paper.clientHeight),ratio=Math.max(1,window.devicePixelRatio||1);if(drawingCanvas.width===Math.round(width*ratio)&&drawingCanvas.height===Math.round(height*ratio))return;const previous=drawingCanvas.width?drawingCanvas.toDataURL('image/png'):'';drawingCanvas.width=Math.round(width*ratio);drawingCanvas.height=Math.round(height*ratio);drawingContext.setTransform(ratio,0,0,ratio,0,0);if(previous){const image=new Image();image.onload=()=>drawingContext.drawImage(image,0,0,width,height);image.src=previous;}}
function loadPageDrawing(data){sizeDrawingCanvas();drawingContext.clearRect(0,0,drawingCanvas.clientWidth,drawingCanvas.clientHeight);if(!data)return;const image=new Image();image.onload=()=>drawingContext.drawImage(image,0,0,drawingCanvas.clientWidth,drawingCanvas.clientHeight);image.src=data;}
function setPenTool(tool){penTool=tool;const drawingActive=tool!=='text';drawingCanvas.classList.toggle('active',drawingActive);$('#paper').classList.toggle('drawing-active',drawingActive);$('#drawingMode').classList.toggle('active',tool==='draw');$('#eraserMode').classList.toggle('active',tool==='erase');$('#textWritingMode').classList.toggle('active',tool==='text');$('#penStatus').textContent=tool==='text'?'Modo escrita ativado. Toque na folha para digitar.':tool==='erase'?'Borracha ativada. Passe sobre os traços.':'Modo desenho ativado.';if(tool==='text'){$('#paperContent').focus();}}
function canvasPoint(event){const rect=drawingCanvas.getBoundingClientRect();return{x:event.clientX-rect.left,y:event.clientY-rect.top};}
drawingCanvas.addEventListener('pointerdown',event=>{if(penTool==='text')return;event.preventDefault();drawing=true;lastDrawPoint=canvasPoint(event);drawingCanvas.setPointerCapture(event.pointerId);});
drawingCanvas.addEventListener('pointermove',event=>{if(!drawing)return;event.preventDefault();const point=canvasPoint(event);drawingContext.save();drawingContext.globalCompositeOperation=penTool==='erase'?'destination-out':'source-over';drawingContext.strokeStyle=penColor;drawingContext.lineWidth=penTool==='erase'?penSize*3:penSize;drawingContext.lineCap='round';drawingContext.lineJoin='round';drawingContext.beginPath();drawingContext.moveTo(lastDrawPoint.x,lastDrawPoint.y);drawingContext.lineTo(point.x,point.y);drawingContext.stroke();drawingContext.restore();lastDrawPoint=point;});
function finishDrawing(event){if(!drawing)return;drawing=false;lastDrawPoint=null;if(event?.pointerId!==undefined&&drawingCanvas.hasPointerCapture(event.pointerId))drawingCanvas.releasePointerCapture(event.pointerId);saveCurrent();}
drawingCanvas.addEventListener('pointerup',finishDrawing);drawingCanvas.addEventListener('pointercancel',finishDrawing);drawingCanvas.addEventListener('pointerleave',event=>{if(drawing&&event.buttons===0)finishDrawing(event);});
