const answers = {fotossíntese:'A fotossíntese é como a cozinha das plantas: usando luz do sol, água e gás carbônico, ela produz açúcar para ter energia e libera oxigênio. Acontece principalmente nas folhas, graças à clorofila.',equação:'Para resolver uma equação de 1º grau, deixe o x sozinho em um lado do sinal de igual. Exemplo: 2x + 4 = 10. Tire 4 dos dois lados: 2x = 6. Depois divida ambos por 2: x = 3.',resumo:'Para criar um bom resumo: 1) leia o assunto, 2) anote só as ideias principais com suas palavras, 3) use títulos e exemplos, e 4) releia tentando explicar sem olhar. Posso ajudar se você colar o texto aqui.',alura:'Nas aulas da Alura, pause quando surgir um conceito novo, anote a ideia principal e teste o que foi mostrado. Se você me disser o tema ou colar um trecho da aula, eu explico passo a passo com exemplos.',duolingo:'Posso ajudar nos seus estudos do Duolingo. Informe sua conta e o progresso no cartão Duolingo abaixo para salvá-los no Caderno Digital, ou diga qual idioma e assunto você está estudando.'};
function reply(question){const q=question.toLowerCase();if(q.includes('fotossíntese'))return answers.fotossíntese;if(q.includes('equação')||q.includes('primeiro grau'))return answers.equação;if(q.includes('resumo'))return answers.resumo;if(q.includes('alura'))return answers.alura;if(q.includes('duolingo'))return answers.duolingo;return 'Ótima pergunta! Para estudar esse assunto, comece identificando os conceitos principais e procurando um exemplo prático. Conte qual parte está mais difícil ou cole um trecho do material que eu explico de um jeito mais simples.';}
function addMessage(text,type,question=''){const m=document.createElement('div');m.className='message '+type;const content=document.createElement('span');content.textContent=text;m.append(content);if(type==='luma'&&question){const save=document.createElement('button');save.className='save-response-card';save.textContent='＋ Salvar como flashcard';save.onclick=()=>addResponseCard(question,text);m.append(save);}$('#chatBox').append(m);$('#chatBox').scrollTop=$('#chatBox').scrollHeight;}
$('#aiForm').onsubmit=e=>{e.preventDefault();const input=$('#aiQuestion'),q=input.value.trim();if(!q)return;addMessage(q,'user');input.value='';setTimeout(()=>addMessage(reply(q),'luma',q),250);};$$('.suggestions button').forEach(b=>b.onclick=()=>{$('#aiQuestion').value=b.dataset.question;$('#aiForm').requestSubmit();});

